#include <iostream>
#include <stdexcept>
#include <vector>

int main() {
    const std::vector<int> durations{10, 20, 5};
    int total = 0;
    for (int n : durations) { // Copy each small integer, not the container.
        if (n < 0 || n > 10000 - total) {
            throw std::invalid_argument("duration or budget");
        }
        total += n;
    }
    std::cout << "flat total=" << total << '\n';
}

#include <iostream>
#include <vector>

struct Node {
    int own_minutes;
    std::vector<Node> children;
};
int recursive_total(const Node& node) {
    int total = node.own_minutes;
    for (const Node& child : node.children) {
        total += recursive_total(child); // Apply the same question below.
    }
    return total;
}
int main() {
    const Node project{0, {{0, {{10, {}}, {20, {}}}}, {5, {}}}};
    int shallow = project.own_minutes;
    for (const Node& child : project.children) shallow += child.own_minutes;
    std::cout << "shallow=" << shallow << '\n';
    std::cout << "recursive=" << recursive_total(project) << '\n';
}
